//! 🧪️ Genuine take transitions return direct work and preserve the same finite source bank.
use semio_framework_value_retained_clone::*;
use semio_framework_value_derive::{RetainedClone,RetireOwned};
#[path="../../🧪️tests/⏱️effect/🦀️.rs"]
mod effect;
#[derive(Debug,PartialEq,serde::Serialize,RetainedClone,RetireOwned)]
#[value(crate="semio_framework_value_retained_clone")]
enum Choice{Empty,Record{label:String,values:Vec<u64>},Tuple(String,u64)}
#[derive(Debug,PartialEq,serde::Serialize,RetainedClone,RetireOwned)]
#[value(crate="semio_framework_value_retained_clone")]
struct Record{label:String,values:Vec<u64>}
use semio_framework_value_testing_allocator::observe_retirement_allocations as heap;
struct Bank{remaining:RetainedCloneGrant,fuel:u64,maximum_work:u64,items:usize}
impl Bank{
 fn new(law:&serde_json::Value)->Self{let s=&law["stock"];Self{fuel:s["work"].as_u64().unwrap(),maximum_work:law["maximumWorkPerTurn"].as_u64().unwrap(),items:law["maximumItemsPerTurn"].as_u64().unwrap()as usize,remaining:RetainedCloneGrant{maximum_items:s["items"].as_u64().unwrap()as usize,maximum_copy_bytes:s["copy"].as_u64().unwrap()as usize,maximum_capacity_bytes:s["capacity"].as_u64().unwrap()as usize,maximum_release_bytes:s["release"].as_u64().unwrap()as usize,maximum_depth:s["depth"].as_u64().unwrap()as usize}}}
 fn grant(&self,d:RetirementDemand)->RetainedCloneGrant{let g=RetainedCloneGrant{maximum_items:self.items.min(self.remaining.maximum_items),maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth};assert!(g.maximum_items<=self.remaining.maximum_items&&g.maximum_copy_bytes<=self.remaining.maximum_copy_bytes&&g.maximum_capacity_bytes<=self.remaining.maximum_capacity_bytes&&g.maximum_release_bytes<=self.remaining.maximum_release_bytes&&g.maximum_depth<=self.remaining.maximum_depth);g}
 fn admitted(&mut self,work:u128,p:RetainedCloneProgress){assert!(p.fits(self.remaining));self.fuel=self.fuel.checked_sub(u64::try_from(work).unwrap()).unwrap();self.remaining.maximum_items-=p.copied_items;self.remaining.maximum_copy_bytes-=p.copied_bytes;self.remaining.maximum_capacity_bytes-=p.retained_capacity_bytes;self.remaining.maximum_release_bytes-=p.released_bytes;}
 fn debit(&mut self,work:u128,p:RetainedCloneProgress,h:(usize,usize)){let work=u64::try_from(work).unwrap();assert!(work<=self.fuel&&work<=self.maximum_work);assert!(p.fits(self.remaining));assert_eq!(h,(p.retained_capacity_bytes,p.released_bytes));self.fuel=self.fuel.checked_sub(work).unwrap();self.remaining.maximum_items-=p.copied_items;self.remaining.maximum_copy_bytes-=p.copied_bytes;self.remaining.maximum_capacity_bytes-=p.retained_capacity_bytes;self.remaining.maximum_release_bytes-=p.released_bytes;}
}
fn round<T:RetainedClone+Sync+'static+serde::Serialize+PartialEq+std::fmt::Debug>(value:T,law:&serde_json::Value){
 let expected=serde_json::to_value(&value).unwrap();let mut bank=Bank::new(law);let body=law["body"].as_u64().unwrap()as usize;let limit=law["maximumTurns"].as_u64().unwrap();
 let(mut source,p,work)=effect::admit(value);bank.admitted(work,p);let pointer=source.borrow().get()as*const T;let mut cursor=T::retained_clone_cursor();
 let(turn,h)=heap(||effect::take(&mut cursor,Default::default()));assert_eq!(turn.work,u128::from(law["deniedWork"].as_u64().unwrap()));assert!(turn.result.unwrap().is_none());assert_eq!(h,(0,0));
 for _ in 0..limit{if cursor.output_ready(){break}let maximum=bank.maximum_work.min(bank.fuel);let g=bank.grant(cursor.advance_demands(source.borrow(),body,maximum).unwrap());let selected=cursor.advance_work_demand(source.borrow(),body,maximum).unwrap();assert!(selected<=maximum);let low=cursor.advance_work_demand(source.borrow(),body,1).unwrap();if low>1{assert_eq!(cursor.advance_work_demand(source.borrow(),body,low).unwrap(),low,"the minimum quote above a 1-unit limit is limit-independent");}if low!=1{let(t,h)=heap(||effect::advance(&mut cursor,source.borrow(),body,1,g));assert_eq!(t.work,0,"{} low-limit denial",std::any::type_name::<T>());assert_eq!(t.result.unwrap().progress(),Default::default());assert_eq!(h,(0,0));}let(denied,h)=heap(||effect::advance(&mut cursor,source.borrow(),body,0,g));assert_eq!(denied.work,0);assert_eq!(denied.result.unwrap().progress(),Default::default());assert_eq!(h,(0,0));let(turn,h)=heap(||effect::advance(&mut cursor,source.borrow(),body,maximum,g));let work=turn.work;assert!(work<=u128::from(selected));let p=turn.result.unwrap().progress();bank.debit(work,p,h);assert_eq!(source.borrow().get()as*const T,pointer);assert_eq!(serde_json::to_value(source.borrow().get()).unwrap(),expected);}
 assert!(cursor.output_ready());let d=cursor.take_demand().unwrap();let header=2*std::mem::size_of::<Option<T>>()+std::mem::size_of::<T>();assert!(d.copy_bytes>=header&&d.copy_bytes-header<=std::mem::size_of::<usize>());let g=bank.grant(d);
 for denied in[RetainedCloneGrant{maximum_items:0,..g},RetainedCloneGrant{maximum_depth:0,..g}]{let(turn,h)=heap(||effect::take(&mut cursor,denied));assert_eq!(turn.work,u128::from(law["deniedWork"].as_u64().unwrap()));assert!(turn.result.unwrap().is_none());assert_eq!(h,(0,0));assert!(cursor.output_ready());}
 let(turn,h)=heap(||effect::take(&mut cursor,g));let work=turn.work;assert_eq!(work,u128::from(law["handoffWork"].as_u64().unwrap()));let(value,p)=turn.result.unwrap().unwrap();bank.debit(work,p,h);assert_eq!(value,*source.borrow().get());assert_eq!(serde_json::to_value(&value).unwrap(),expected);let(turn,h)=heap(||effect::take(&mut cursor,Default::default()));assert_eq!(turn.work,u128::from(law["cachedWork"].as_u64().unwrap()));assert!(turn.result.unwrap().is_none());assert_eq!(h,(0,0));
 let q=cursor.begin_close_work_demand().unwrap();assert!(q<=bank.fuel&&q<=bank.maximum_work);let sg=bank.grant(cursor.begin_close_demand().unwrap());let(t,h)=heap(||effect::begin_close_paid(&mut cursor,sg));assert_eq!(t.work,u128::from(q),"begin_close work of {}",std::any::type_name::<T>());let p=t.result.unwrap();bank.debit(t.work,p,h);for _ in 0..limit{if cursor.terminal_is_empty(){break}let g=bank.grant(cursor.close_demands(body).unwrap());let q=cursor.close_work_demand(body).unwrap();assert!(q<=bank.fuel&&q<=bank.maximum_work);let(turn,h)=heap(||effect::close_step(&mut cursor,g));let work=turn.work;bank.debit(work,turn.result.unwrap().progress(),h);}assert!(cursor.terminal_is_empty());
 let mut value=Some(value);let mut close=RetainedCloneClose::default();for _ in 0..limit{if value.is_none()&&close.is_empty(){break}let g=bank.grant(close.next_owner_demands::<T>(value.is_some(),&None,body).unwrap());let q=close.next_owner_work::<T>(value.is_some(),&None,body).unwrap();assert!(q<=bank.fuel&&q<=bank.maximum_work);let(turn,h)=heap(||if close.is_empty(){let turn=effect::begin_granted(&mut close,&mut value,g);RetainedWorkOutcome{work:turn.work,result:turn.result.map(|step|step.unwrap_or(RetainedCloneStep::Progress(Default::default()))).map_err(Into::into)}}else{effect::step_granted(&mut close,g)});let work=turn.work;bank.debit(work,turn.result.unwrap().progress(),h);}assert!(value.is_none()&&close.is_empty());
 for _ in 0..limit{if source.terminal_is_empty(){break}let g=bank.grant(source.next_close_demand(body).unwrap());let q=source.next_close_work_demand(body).unwrap();assert!(q<=bank.fuel&&q<=bank.maximum_work);let(turn,h)=effect::driven(g,|e|source.close_step(body,e));let work=turn.work;bank.debit(work,turn.result.unwrap().progress(),h);}assert!(source.terminal_is_empty());assert_eq!(heap(||drop((cursor,source,close))).1,(0,0));
}
#[test]
fn original_clone_take_owns_work_quote_denial_cached_and_every_output_close(){
 let law:serde_json::Value=serde_json::from_str(include_str!("take.json")).unwrap();let schema:serde_json::Value=serde_json::from_str(include_str!("take.schema.json")).unwrap();for(k,v)in law.as_object().unwrap(){assert_eq!(&schema["properties"][k]["const"],v);}let c=&law["cases"];
 round(serde_json::from_value::<u64>(c["scalar"].clone()).unwrap(),&law);round(serde_json::from_value::<String>(c["text"].clone()).unwrap(),&law);round(Some(serde_json::from_value::<String>(c["optional"].clone()).unwrap()),&law);round(serde_json::from_value::<Vec<String>>(c["vector"].clone()).unwrap(),&law);round(serde_json::from_value::<[String;2]>(c["array"].clone()).unwrap(),&law);round(serde_json::from_value::<(String,String)>(c["tuple"].clone()).unwrap(),&law);round(Box::new(serde_json::from_value::<String>(c["boxed"].clone()).unwrap()),&law);
 round(Record{label:serde_json::from_value(c["enumRecord"]["label"].clone()).unwrap(),values:serde_json::from_value(c["enumRecord"]["values"].clone()).unwrap()},&law);
 assert_eq!(c["enumEmpty"],true);round(Choice::Empty,&law);round(Choice::Record{label:serde_json::from_value(c["enumRecord"]["label"].clone()).unwrap(),values:serde_json::from_value(c["enumRecord"]["values"].clone()).unwrap()},&law);round(Choice::Tuple(serde_json::from_value(c["enumTuple"][0].clone()).unwrap(),serde_json::from_value(c["enumTuple"][1].clone()).unwrap()),&law);
}
